<?php
/** Proof — bulk (spec "Proof", 4): three tickets, one closed: two change and the closed one is reported with "cannot move from Closed."; the note lands on the two; Priya → 403; without confirmed → 422 "Confirm the change to 3 tickets."; the inbox's selection; JSON. */
require __DIR__ . '/lib.php';
$W = world();
$marco = as_member(27); $lena = as_member(28); $priya = as_member(26);
$a = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE bulk a', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
$b2 = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE bulk b', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
$c3 = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE bulk c (closed)', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
act($marco, '/tickets/transition.php', ['ticket' => $c3, 'status' => 'open']);
act($lena, '/tickets/close.php', ['ticket' => $c3, 'resolution_code' => 'resolved']);
echo "1. The screen\n";
[$c, $d] = screen($lena, '/bulk?tickets=' . $a . ',' . $b2 . ',' . $c3 . ',' . $W['t_fac']);
ok($c === 200 && array_map(fn ($t) => $t['ticket_id'], $d['tickets']) === [$a, $b2, $c3, $W['t_fac']], 'Lena (view_all) sees all four listed in the order given');
[$c, $d] = screen($marco, '/bulk?tickets=' . $a . ',' . $b2 . ',' . $W['t_fac']);
ok(page($marco, '/bulk?tickets=' . $a)['code'] === 403, 'Marco (support): 403 (tickets.manage)');
ok(page($priya, '/bulk?tickets=' . $a)['code'] === 403, 'Priya: 403');
$body = page($lena, '/bulk?tickets=' . $a . ',' . $b2 . ',' . $c3)['body'];
ok(str_contains($body, 'id="bulk-target-' . $c3 . '"') && str_contains($body, 'id="bulk-form-field-confirmed"') && str_contains($body, 'Apply to 3 tickets'), 'the page lists them and asks to confirm');
$inbox = page($lena, '/inbox')['body'];
ok(str_contains($inbox, 'id="ticket-list-bulk-btn"') && str_contains($inbox, 'id="ticket-row-' . $a . '-pick"') && str_contains($inbox, 'id="ticket-card-' . $a . '-pick"'), 'the inbox has the checkboxes and Change selected… for a lead');
ok(!str_contains(page($marco, '/inbox')['body'], 'id="ticket-list-bulk-btn"'), 'and not for support');
echo "2. The change\n";
[$c, $b] = act($lena, '/bulk/update.php', ['tickets' => [$a, $b2, $c3], 'status' => 'open', 'note' => 'SMOKE bulk note', 'add_tags' => 'outage', 'priority' => 'high']);
ok($c === 422 && msg($b) === 'Confirm the change to 3 tickets.', 'without confirmed: 422 "Confirm the change to 3 tickets."');
[$c, $b] = act($priya, '/bulk/update.php', ['tickets' => [$a], 'status' => 'open', 'confirmed' => 'yes']);
ok($c === 403, 'Priya\'s POST: 403');
[$c, $b] = act($marco, '/bulk/update.php', ['tickets' => [$a], 'status' => 'open', 'confirmed' => 'yes']);
ok($c === 403, 'Marco\'s POST: 403');
[$c, $b] = act($lena, '/bulk/update.php', ['tickets' => [$a, $b2, $c3], 'confirmed' => 'yes']);
ok($c === 422 && msg($b) === 'Say what to change.', 'nothing to change: 422');
$since = last_activity_id();
[$c, $b] = act($lena, '/bulk/update.php', ['tickets' => [$a, $b2, $c3], 'status' => 'open', 'note' => 'SMOKE bulk note', 'add_tags' => 'outage', 'priority' => 'high', 'assignee' => 'me', 'confirmed' => 'yes']);
ok($c === 200 && ($b['changed'] ?? []) === [$a, $b2] && count($b['refused'] ?? []) === 1 && $b['refused'][0]['ticket_id'] === $c3 && $b['refused'][0]['why'] === ticket_row($c3)['number'] . ' cannot move from Closed.', 'two changed, the closed one refused with its sentence');
ok(ticket_status($a) === 'open' && ticket_status($b2) === 'open' && ticket_status($c3) === 'closed' && ticket_row($a)['priority'] === 'high' && (int) ticket_row($a)['assignee_member_id'] === 28 && ticket_row($c3)['priority'] === 'normal', 'the two carry the status, priority and assignee; the closed one is untouched (per-ticket transactions)');
ok((int) one("SELECT count(*) FROM messages WHERE ticket_id IN (:a, :b) AND kind = 'internal_note' AND body_text = 'SMOKE bulk note'", ['a' => $a, 'b' => $b2]) === 2 && (int) one("SELECT count(*) FROM messages WHERE ticket_id = :c AND body_text = 'SMOKE bulk note'", ['c' => $c3]) === 0, 'the note landed on the two only');
$l = activity('ticket.bulk_update', $since);
$after = json_decode((string) ($l[0]['after'] ?? '{}'), true);
ok(count($l) === 1 && $after['ticket_ids'] === [$a, $b2, $c3] && $after['changed'] === [$a, $b2] && count($after['refused']) === 1 && sort($after['changes']) !== null && in_array('note', $after['changes'], true), 'one ticket.bulk_update row with the ids, the change keys, changed and refused');
ok(count(array_filter(activity('ticket.transition', $since), fn ($r) => json_decode($r['after'], true)['via'] === 'bulk')) === 2 && count(activity('ticket.note', $since)) === 2 && count(activity('ticket.assign', $since)) === 2, 'the per-ticket rows: two transitions via bulk, two notes, two assigns');
echo "3. The result page and a plain form\n";
[$c, $html, $h] = hx($lena, '/bulk/update.php', ['tickets' => [$a, $c3], 'remove_tags' => 'outage', 'confirmed' => 'yes'], '#page-content');
ok($c === 200 && str_contains($html, 'id="bulk-result-changed"') && str_contains($html, '2 changed') && !str_contains($html, 'id="bulk-result-refused"') && preg_match('/^HX-Trigger: .*ticketChanged/mi', $h) === 1, 'the result page: both changed (removing a tag is allowed on a closed ticket); HX-Trigger ticketChanged');
[$c, $html, $h] = hx($lena, '/bulk/update.php', ['tickets' => [$a, $c3], 'status' => 'pending', 'confirmed' => 'yes'], '#page-content');
ok($c === 200 && str_contains($html, '1 changed') && str_contains($html, 'id="bulk-result-refused"') && str_contains(html_entity_decode($html, ENT_QUOTES), 'cannot move from Closed.'), 'a refusal is a row with its sentence');
[$c, $b] = act($lena, '/bulk/update.php', ['tickets' => [$a, $b2], 'assignee' => '40', 'confirmed' => 'yes']);
ok($c === 200 && count(dispatches($a)) === 1 && count(dispatches($b2)) === 1, 'assigning to the agent in bulk dispatches each');
[$c, $b] = act($lena, '/bulk/update.php', ['tickets' => [$a, $W['t_fac']], 'priority' => 'low', 'confirmed' => 'yes']);
ok($c === 200 && ($b['changed'] ?? []) === [$a, $W['t_fac']], 'Lena (view_all + manage) changes a Facilities ticket too');
finish();
